mapper.select:
SELECT DATE_FORMAT(pr.purchase_date, '%Y-%m') as month, SUM(pr.total_price) as total_amount, COUNT(*) as count FROM purchase_record pr WHERE pr.deleted = 0
AND pr.user_id = #{userId}
GROUP BY DATE_FORMAT(pr.purchase_date, '%Y-%m') ORDER BY month

SELECT DATE_FORMAT(pr.purchase_date, '%Y-%m-%d') as day, SUM(pr.total_price) as total_amount, COUNT(*) as count FROM purchase_record pr WHERE pr.deleted = 0
AND pr.user_id = #{userId}
AND pr.purchase_date >= #{startDate} GROUP BY DATE_FORMAT(pr.purchase_date, '%Y-%m-%d') ORDER BY day

SELECT DATE_FORMAT(pr.purchase_date, '%Y') as year, SUM(pr.total_price) as total_amount, COUNT(*) as count FROM purchase_record pr WHERE pr.deleted = 0
AND pr.user_id = #{userId}
GROUP BY DATE_FORMAT(pr.purchase_date, '%Y') ORDER BY year
